	GraphReturnedTokens       int64        `json:"graph_returned_est_tokens"`
	ExplorationReturnedBytes  int64        `json:"exploration_returned_bytes"`
	ExplorationReturnedTokens int64        `json:"exploration_returned_est_tokens"`
