		encoder.SetEscapeHTML(false)
		return encoder.Encode(report)
	}
	if flags.Verbose {
		writeStatsText(opts.Stdout, report)
		return nil
	}
	writeStatsSummary(opts.Stdout, report)
	return nil
"}

