		ID      string          `json:"id"`
		Content json.RawMessage `json:"content"`
		Usage   *struct {
			InputTokens     int64 `json:"input_tokens"`
			CacheCreationIn int64 `json:"cache_creation_input_tokens"`
			CacheReadIn     int64 `json:"cache_read_input_tokens"`
