	writeTranscript(t, filepath.Join(sessions, "s1", "subagents"), "agent-2.jsonl",
		toolUseLine(t, now, "Grep", "shared", map[string]any{"pattern": "x"}),
		toolResultLine(t, now, "shared", shared),
	)

