//     every window, and no --since can ever read another's answer.
const statsCacheSchema = "v1"

// statsCacheMinTranscripts is the scope size below which the memo is skipped: reading, decoding
// and rewriting the scope file costs more than re-parsing a handful of transcripts.
const statsCacheMinTranscripts = 8

// statsCacheMaxBytes bounds both compressed and decompressed cache data. A memo is a convenience;
// it is not worth unbounded memory if the file on disk is not what this code wrote.
const statsCacheMaxBytes = 256 << 20

type statsCache struct {
	path    string
	salt    string
	entries map[string]fileSummary // what the next save writes
	changed bool
}

// statsCacheDir decides where the memo lives, following the same precedence as every other
// cache in this binary: --cache-dir, then the data directory Entire hands a plugin, then the
// platform per-user cache root. --no-cache disables it outright.
func statsCacheDir(flags statsFlags, env EntireEnv) string {
	if flags.NoCache {
		return ""
	}
	return resolveCacheDir(flags.CacheDir, env.PluginDataDir)
}

// openStatsCache loads the memo for one scope (a project transcript directory, or a single
// transcript). A nil *statsCache is a working no-op cache, so callers never branch.
func openStatsCache(dir, scope, version string, candidates int) *statsCache {
	if dir == "" || candidates < statsCacheMinTranscripts {
		return nil
	}
	cache := &statsCache{
		path:    filepath.Join(dir, "stats", statsCacheSchema, statsCacheKey(scope)+".json.gz"),
		salt:    statsCacheSalt(version),
		entries: map[string]fileSummary{},
	}
	cache.load()
	return cache
}

// statsCacheSalt mixes everything that can change a summary without changing a transcript: the
// summary schema, the CLI version, and the running executable's own size and modification time.
// The last of those is what makes a rebuilt development binary miss rather than trust a memo
// written by different parsing code.
func statsCacheSalt(version string) string {
	salt := statsCacheSchema + "\x00" + version
	if executable, err := os.Executable(); err == nil {
		if info, err := os.Stat(executable); err == nil {
			salt += "\x00" + executable +
				"\x00" + strconv.FormatInt(info.Size(), 10) +
				"\x00" + strconv.FormatInt(info.ModTime().UnixNano(), 10)
		}
	}
	return salt
}

func statsCacheKey(values ...string) string {
	digest := sha256.New()
	for _, value := range values {
		_, _ = digest.Write([]byte(value))
		_, _ = digest.Write([]byte{0})
	}
	return hex.EncodeToString(digest.Sum(nil))
}

// entryKey identifies one transcript by content-relevant identity, not by name.
func (c *statsCache) entryKey(file transcriptFile) string {
	return statsCacheKey(c.salt, file.path,
		strconv.FormatInt(file.size, 10),
		strconv.FormatInt(file.modTime.UnixNano(), 10))
}

type statsCacheDocument struct {
	Schema  string                 `json:"schema"`
	Entries map[string]fileSummary `json:"entries"`
}

// load reads the memo. Every error path leaves an empty cache: recomputing is always correct,
// a file that survives is still parsed in full and still filtered per session afterwards.
// Pruning is decided per SESSION, not per file, so a subagent transcript can never be separated
// from the transcript that owns it.
func (c *statsCollector) run(files []transcriptFile, cutoff time.Time) {
	c.considered = len(files)
	c.cache.retain(files)
	keep := map[string]bool{}
	for _, file := range files {
		if cutoff.IsZero() || !file.modTime.Before(cutoff) {
			keep[file.session] = true
		}
	}
	for _, file := range files {
		if !keep[file.session] {
			continue
		}
		summary, ok := c.summarise(file)
		if !ok {
			continue
		}
		c.transcripts++
		c.malformed += summary.Malformed
		c.session(file.session).merge(summary)
	}
	c.cache.save()
}

func (c *statsCollector) summarise(file transcriptFile) (fileSummary, bool) {
	if summary, ok := c.cache.lookup(file); ok {
		c.fromCache++
		return summary, true
	}
	summary, ok := summariseTranscript(file.path)
	if !ok {
		return fileSummary{}, false
	}
	c.cache.store(file, summary)
	return summary, true
}

// listTranscriptFiles enumerates the `*.jsonl` in scope with the size and mtime the memo keys
// on. Top-level `<session>.jsonl` files are sessions; subagent transcripts live under
// `<session>/subagents/*.jsonl` and are folded into the owning session so delegated exploration
// is not invisible.
//
// When single is set, root names ONE transcript file rather than a directory: that file plus the
// `<session>/` sibling directory holding its subagent transcripts. Both key to the same session,
// so the accounting is byte-for-byte what the directory walk would produce for that session. It
// exists because a project's transcript directory can reach gigabytes, which a per-render caller
// (status line) cannot afford to walk.
func listTranscriptFiles(root string, single bool) ([]transcriptFile, error) {
	if !single {
		return walkTranscripts(root, root, true)
	}
	base := filepath.Dir(root)
	files := []transcriptFile{}
	if info, err := os.Lstat(root); err == nil && info.Mode().IsRegular() {
		files = append(files, transcriptFile{
			path:    root,
			session: sessionKeyForPath(base, root),
			size:    info.Size(),
			modTime: info.ModTime(),
		})
	}
	subagents := strings.TrimSuffix(root, ".jsonl")
	if subagents == root {
		return files, nil
	}
	if info, err := os.Stat(subagents); err != nil || !info.IsDir() {
		return files, nil //nolint:nilerr // a session without subagent transcripts is the common case
	}
	nested, err := walkTranscripts(subagents, base, false)
	if err != nil {
		return nil, err
	}
	files = append(files, nested...)
	sort.Slice(files, func(i, j int) bool { return files[i].path < files[j].path })
	return files, nil
}

func walkTranscripts(dir, keyRoot string, reportRootError bool) ([]transcriptFile, error) {
	var files []transcriptFile
	err := filepath.WalkDir(dir, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			if reportRootError && path == dir {
				return err
			}
			return nil //nolint:nilerr // an unreadable subtree must not fail the whole report
		}
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".jsonl") {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return nil //nolint:nilerr // a file that vanished mid-walk is simply not reported on
		}
		files = append(files, transcriptFile{
			path:    path,
			session: sessionKeyForPath(keyRoot, path),
			size:    info.Size(),
			modTime: info.ModTime(),
		})
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Slice(files, func(i, j int) bool { return files[i].path < files[j].path })
	return files, nil
}

// sessionKeyForPath folds `<session>/subagents/agent-x.jsonl` back onto `<session>`.
func sessionKeyForPath(root, path string) string {
	rel, err := filepath.Rel(root, path)
	if err != nil {
		return strings.TrimSuffix(filepath.Base(path), ".jsonl")
	}
	parts := strings.Split(filepath.ToSlash(rel), "/")
	if len(parts) > 1 {
		return parts[0]
	}
	return strings.TrimSuffix(parts[0], ".jsonl")
}

